const __raw = $input.item.json.body || {};
const body = { ...__raw };
for (const __k in __raw) { const __v = __raw[__k]; if (__v && typeof __v === 'object' && !Array.isArray(__v)) Object.assign(body, __v); }

const rawQuery = (body.query || body.sku || body.name || '').toString().trim();
if (!rawQuery) {
  return { json: { hasQuery: false, query: '', cleanQuery: '', tokens: [], filter: 'sku.eq.__no_query__' } };
}

const clean = rawQuery.replace(/[^a-zA-Z0-9\s\-_]/g, ' ').replace(/\s+/g, ' ').trim();
const stop = new Set(['the','a','an','for','of','to','and','or','please','can','you','i','we','do','does','have','has','is','are','me','my','our','your','service','services','price','pricing','cost','costs','stock','availability','available','about','on','in','it','this','that','with','how','much','many','need','want','looking','check','tell','give','know','there','their','a']);
let tokens = clean.split(' ').filter(t => t.length >= 2 && !stop.has(t.toLowerCase()));
if (tokens.length === 0) tokens = clean.split(' ').filter(Boolean);

const enc = s => encodeURIComponent(s);
const parts = [];
// Full phrase first (best relevance), then any individual keyword.
parts.push('sku.ilike.*' + enc(clean) + '*');
parts.push('name.ilike.*' + enc(clean) + '*');
for (const t of tokens) {
  parts.push('sku.ilike.*' + enc(t) + '*');
  parts.push('name.ilike.*' + enc(t) + '*');
}
const filter = 'or=(' + parts.join(',') + ')';

return { json: { hasQuery: true, query: rawQuery, cleanQuery: clean, tokens, filter } };

const inputData = $input.all();
const originalQuery = $('Sanitize Query').first().json.query || 'the item';

let product = null;
if (inputData && inputData.length > 0 && inputData[0].json) {
  if (Array.isArray(inputData[0].json) && inputData[0].json.length > 0) {
    product = inputData[0].json[0];
  } else if (inputData[0].json.sku) {
    product = inputData[0].json;
  }
}

if (product) {
  const inStock = (product.stock_quantity || 0) > 0;
  const priceStr = parseFloat(product.price || 0).toFixed(2);
  const spoken = inStock
    ? `Yes, we have ${product.name} in stock for $${priceStr}. We currently have ${product.stock_quantity} available.`
    : `We carry ${product.name} for $${priceStr}, but it is currently out of stock. Would you like me to check when our next shipment arrives?`;

  return {
    json: {
      found: true,
      sku: product.sku,
      name: product.name,
      category: product.category || 'General',
      price: parseFloat(product.price || 0),
      currency: product.currency || 'USD',
      in_stock: inStock,
      quantity: product.stock_quantity || 0,
      description: product.description || '',
      spoken_summary: spoken
    }
  };
} else {
  return {
    json: {
      found: false,
      query: originalQuery,
      in_stock: false,
      quantity: 0,
      spoken_summary: `I checked our catalog, but I could not find a match for ${originalQuery}. Would you like me to check a different keyword or have a specialist call you back?`
    }
  };
}
